select 

where s.ses_room_token = #{roomToken}
limit 1

select a.apt_id
from t_sch_appointment a
join t_pos p on p.pos_id = a.apt_position_id
where a.apt_candidate_id = #{candidateId}
  and p.pos_company_id = #{companyId}
  and a.apt_status in (0, 1)

select count(*) from t_app_record
where app_candidate_id = #{candidateId} and app_position_id = #{positionId}
  and app_status not in (2, 9)

mapper.update:
update t_int_meeting_state
set mst_updated_at = sysdate()
, mst_mic_enabled = #{micEnabled,jdbcType=TINYINT}
, mst_cam_enabled = #{camEnabled,jdbcType=TINYINT}
, mst_speaker_volume = #{speakerVolume,jdbcType=TINYINT}
, mst_device_json = #{deviceJson,jdbcType=VARCHAR}
where mst_session_id = #{sessionId}

update t_int_meeting_state
set mst_heartbeat_at = sysdate(), mst_updated_at = sysdate()
where mst_session_id = #{sessionId}

update t_int_meeting_state
set mst_current_question = mst_current_question + 1, mst_updated_at = sysdate()
where mst_session_id = #{sessionId}

mapper.select:
select cpt_id as id, cpt_session_id as sessionId, cpt_status as status
from t_int_copilot
where cpt_id = #{id}

select r.rcd_id as recordingId, r.rcd_code as code, r.rcd_session_id as sessionId, s.ses_candidate_id as candidateId, ifnull(u.nick_name, u.user_name) as candidateName, p.pos_title as positionTitle, date_format(r.rcd_start_at, '%Y-%m-%d') as interviewDate, date_format(r.rcd_start_at, '%Y-%m-%d %H:%i:%s') as startedAt, ifnull(r.rcd_duration_sec, 0) as durationSec, r.rcd_size_bytes as recSizeBytes, r.rcd_status as status, s.ses_mode as mode, r.rcd_url as recUrl, r.rcd_access_level as recAccessLevel, date_format(r.rcd_expires_at, '%Y-%m-%d') as recExpiresAt from t_int_recording r join t_int_session s on s.ses_id = r.rcd_session_id join t_pos p on p.pos_id = s.ses_position_id join t_tal t on t.tal_id = s.ses_candidate_id join sys_user u on u.user_id = t.tal_user_id where p.pos_company_id = #{companyId}
and r.rcd_id = #{recordingId}
and r.rcd_session_id = #{sessionId}
and s.ses_candidate_id = #{candidateId}
and t.tal_user_id = #{candidateUserId}
and (u.nick_name like concat('%', #{candidate}, '%') or u.user_name like concat('%', #{candidate}, '%'))
and r.rcd_start_at >= #{from}
and r.rcd_start_at <= concat(#{to}, ' 23:59:59')
order by r.rcd_start_at desc, r.rcd_id desc

select d.dlg_order as sequence, d.dlg_role as role, d.dlg_content as content, greatest(ifnull(timestampdiff(second, #{startAt}, d.dlg_created_at), 0), 0) as second from t_int_dialogue d where d.dlg_session_id = #{sessionId}
and d.dlg_created_at >= #{startAt}
order by d.dlg_order asc

