update t_int_session_interviewer
set isi_accept_status = #{acceptStatus}, isi_updated_at = sysdate()
where isi_session_id = #{sessionId} and isi_user_id = #{userId}

update t_int_session_interviewer
set isi_is_primary = 0, isi_updated_at = sysdate()
where isi_session_id = #{sessionId}

update t_int_session
set ses_interviewer_id = #{userId}, ses_updated_at = sysdate()
where ses_id = #{sessionId}
